import pointer
assert pointer.resolve({'a': {'b': [10,20]}}, '/a/b/1') == 20
assert pointer.resolve({'a/b': 1}, '/a~1b') == 1
assert pointer.resolve({'m~n': 2}, '/m~0n') == 2
assert pointer.resolve({'': 3}, '/') == 3
assert pointer.resolve({'a':[{'b':4}]}, '/a/0/b') == 4
assert pointer.resolve({'x': 5}, '') == {'x': 5}
for bad in ['a', '/a~2b']:
    try: pointer.resolve({'a':1}, bad)
    except ValueError: pass
    else: raise AssertionError('expected ValueError: '+bad)
try: pointer.resolve({'a':1}, '/missing')
except KeyError: pass
else: raise AssertionError('expected KeyError')
